# Distinguish a pint Quantity from an astropy Quantity WITHOUT importing
# either: pint exposes `.units` (not `.unit`), and its Unit exposes `._units`
# (a dict of full-name -> exponent).  astropy exposes `.unit` + `.unit.bases`.
_PINT_UNITS_ATTR = "_units"
_PINT_QUANTITY_ATTR = "units"

# SysML keywords that are NOT valid bare IDs and so must be 'quoted' when used
# as a member name in a unit bracket / import (W2-4).
_UNIT_KEYWORD_NAMES = frozenset(
    {
        "in",
        "out",
        "inout",
        "all",
        "optional",
        "unique",
        "variant",
        "ordered",
        "nonunique",
        "redefines",
        "refines",
        "specializes",
        "import",
        "attribute",
        "part",
        "package",
        "comment",
        "public",
        "private",
        "protected",
        "readonly",
    }
)


def _quote_unit_name(name: str) -> str:
    """Quote ``name`` if it is not a valid bare SysML ID (W2-4).

    ``%``, or a keyword like ``in``/``out``, must be written ``'%'``/``'in'``
    so it tokenizes as a name, not an operator/keyword."""
    if not name:
        return "''"
    is_plain = (name[0].isalpha() or name[0] == "_") and (
        name.isalnum() or all(c.isalnum() or c == "_" for c in name[1:])
    )
    if is_plain and name not in _UNIT_KEYWORD_NAMES:
        return name
    return f"'{name}'"


def _unit_sysml_name(astropy_base: str) -> str:
    """The SysML member name for an astropy base (W2-5)."""
    return _UNIT_SYSML_NAME.get(astropy_base, astropy_base)


def _unit_import_spec(astropy_base: str) -> tuple[str, str]:
    """The ``(namespace, sysml_name)`` import for an astropy base (W2-4/5)."""
    ns = _UNIT_NAMESPACE[astropy_base]
    return ns, _quote_unit_name(_unit_sysml_name(astropy_base))


def _build_unit_bracket(bases: list[str], powers: list[int]) -> str:
    """Build the SysML bracket spelling from structured astropy bases/powers.

    Rules (all r3 fixes):
    - Positive powers PRODUCT is joined with ``*`` (``(N, m)`` powers
      ``(1, 1)`` -> ``'N*m'``).
    - Non-±1 powers use the grammar's exponent operator ``**`` — ``(m, s)``
      powers ``(1, -2)`` -> ``'m/s**2'``.  A digit-suffixed ``s2`` would be a
      *member identifier reference*, not an exponent, and would disagree with
      the emitted ``SI::s`` import (W1-1).
    - With no positive power, a leading ``1`` numerator is supplied:
      ``(s,)`` powers ``(-1,)`` -> ``'1/s'``, not ``'/s'`` (W1-2).
    - A dimensionless unit (empty bases) -> an empty bracket ``''`` (W2-1).
    - Names go through the astropy->SysML map and quoting (``'in'``, ``'%'``).
    - Non-integer powers raise (W2-2).
    No spaces — matches the corpus ``= 1000[kg]`` and ``[mi / gal]``.
    """
    numer: list[str] = []
    denom: list[str] = []
    for base, power in zip(bases, powers):
        p = int(power)
        if power != p:  # non-integer (fractional) power -> fail loud
            raise ValueError(
                f"unit power {power!r} on base {base!r} is not an integer; "
                f"fractional powers cannot be rendered faithfully in SysML"
            )
        if p == 0:
            continue
        nm = _quote_unit_name(_unit_sysml_name(base))
        if p > 0:
            numer.append(nm if p == 1 else f"{nm}**{p}")
        else:
            denom.append(nm if p == -1 else f"{nm}**{-p}")
    if not numer and not denom:
        return ""  # dimensionless
    num = "*".join(numer) if numer else "1"
    if denom:
        # join denominators with `/`, NOT `*` (r5 W1-1): the grammar folds
        # `*` and `/` into ONE left-associative precedence level, so `a/b*c`
        # parses as `(a/b)*c` — multipliers would move divisor bases back into
        # the numerator and silently change the dimension.  Left-associative
        # chained division `a/b/c` reads as `a/(b*c)`, which is exactly the
        # term(-1) reading, so this is correct AND idempotent.
        return f"{num}/{'/'.join(denom)}"
    return num


def _parse_unit_terms(unit_string: str) -> list[tuple[str, int]]:
    """Parse a raw ``unit=`` string into ``(base, power)`` terms (r4 W1-1).

    Single source of truth for the string path: BOTH the bracket and the
    bases are derived from ONE parse, so imports and spelling can never
    diverge.  Handles ``s**2``/``s^2``/``s2`` (and negative exponents),
    ``m/s``, ``m/s/s`` (== ``m/(s*s)``), ``kg*m/s**2`` and ``mi/gal``.

    ``a/b/c`` is read as ``a/(b*c)`` (SysML / is non-associative, so a
    multi-slash quantity means an iterated product of divisors).  NOTE: a
    mixed-operator string like ``a/b*c`` is also read as ``a/(b*c)`` — the
    builder never emits that shape (its divisor joins use ``/``), so
    idempotence is unaffected; it only changes the informal interpretation
    of a user-authored mixed-operator string (r6 note 2)."""
    head, sep, tail = unit_string.partition("/")
    groups = [(head, 1), (tail, -1)] if sep else [(head, 1)]
    terms: list[tuple[str, int]] = []
    for text, sign in groups:
        for token in text.replace("**", "^").replace("*", " ").replace("/", " ").split():
            if token == "1":
                continue  # the bare `1` numerator of `1/s` carries no scale
            if token.isdigit() or _is_float_literal(token):
                # a bare magnitude like `100 m` or `m/100` is a multiplicative
                # scale factor — same silent-magnitude class the Quantity path
                # fails loud on (scale != 1), so the two paths must agree (r5)
                raise ValueError(
                    f"unit string {unit_string!r} has a multiplicative scale "
                    f"factor ({token!r}); scaled units cannot be rendered "
                    f"faithfully in SysML — use a plain unit without the "
                    f"magnitude"
                )
            base, sep2, exp = token.partition("^")
            if not sep2:
                # digit-suffix form: 's2' -> base 's', exp '2'
                trimmed = base.rstrip("0123456789")
                base, exp = trimmed, base[len(trimmed) :]
            # strip a quoted name (`'in'`/`'%'`) fed back from a previous
            # normalization so `unit=` is idempotent over quoted units (r4)
            if len(base) >= 2 and base[0] == base[-1] == "'":
                base = base[1:-1]
            try:
                power = int(exp or 1)
            except ValueError:
                raise ValueError(
                    f"unit string {unit_string!r} has a malformed exponent "
                    f"{exp!r} on base {base!r}; expected an integer"
                ) from None
            terms.append((base, sign * power))
    return terms


def _is_float_literal(token: str) -> bool:
    """True for a bare numeric token (``100``, ``2.5``) — a scale factor, not
    a unit base."""
    try:
        float(token)
        return True
    except ValueError:
        return False


def _split_unit_bases(unit_string: str) -> list[str]:
    """Parse a raw ``unit=`` string into its base names (string path only)."""
    return [base for base, _ in _parse_unit_terms(unit_string)]


def _normalize_unit_string(unit_string: str) -> str:
    """Normalize a raw ``unit=`` string to its SysML bracket form.

    ``'m / s2'`` -> ``'m/s**2'``, ``'m/s**2'`` -> ``'m/s**2'`` (idempotent on
    the builder's own output — r4 W1-1).  This is the SAME normalization a
    Quantity derives from its structured bases, so an explicit ``unit=`` and
    a Quantity's own unit compare equal when they denote the same unit.
    Raises ValueError for a unit with no parseable base."""
    terms = _parse_unit_terms(unit_string)
    if not terms:
        raise ValueError(
            f"unit={unit_string!r} has no parseable unit base; expected "
            f"something like 'm', 'kg', 'm/s**2' (got no unit name)"
        )
    bases = [base for base, _ in terms]
    powers = [power for _, power in terms]
    return _build_unit_bracket(bases, powers)


# IR kinds that carry a `value` field (W2-1) — Feature usages whose grammar
# has a `= value`.  Definition kinds have no value IR field (a `def` cannot
# carry a FeatureValue), Package/Comment/Import and Relationship kinds have
# no value either; a value=/unit= there would be silently dropped from
# build() while showing in dump(), so it must be rejected.
# This set is deliberately CONSERVATIVE: it lists only the usage kinds the
# corpus demonstrably gives a `= value` (r3 N-4).  The review suggested
# widening it to actor/objective/connection/succession/transition; nothing in
# the corpus shows those carrying `= value`, so adding them could instead EMIT
# invalid output.  Over-restriction (fail-loud TypeError) is the safe
# direction — it can never produce silently-wrong model text, only an explicit
# error.  If a real model needs one, add the kind here alongside a corpus
# proof, not speculatively.
_VALUE_BEARING_KINDS = frozenset(
    {
        "attribute",
        "part",
        "item",
        "reference",
        "port",
        "action",
        "state",
        "occurrence",
        "requirement",
        "constraint",
        "interface",
        "use_case",
        "subject",
    }
)


class Builder:
    """Base builder: accumulates a canonical-IR dict sub-tree.

    ``build()`` returns the IR dict, ``build_node()`` lifts it through
    ``Node.from_ir``, and ``dump()`` renders textual SysML via the syntactic
    ``_render_sysml`` emitter (which the lab's ``parse_ir`` recovers).
    """

    kind = ""
    ir_kind = ""  # coarse canonical-IR kind (W1-3); set per builder class
    owned_body = None  # e.g. "PackageBody" — advisory legal-child body
    _is_definition = False

    def __init__(self, name=None, *, kind=None, value=None, unit=None):
        self._name = name
        self._short_name = None
        self._text = None
        self._multiplicity = None
        self._value = None
        self._unit = None
        self._unit_bases = None
        self._modifiers: dict[str, object] = {}
        self._typed_by = None
        # Issue #27: separate TWO roles the old code conflated (review W1-3):
        #   - `self._kind`    : the IR ALIAS key (used by `_to_ir()` for the
        #                       round-trip cast; MUST be an IR_KIND_ALIASES
        #                       key, e.g. "part", "part def", "use_case").
        #   - `self._keyword` : the printable SysML keyword (used by
        #                       `_render_sysml()`, e.g. "part", "part def",
        #                       "use case").  Conflating them made
        #                       `UseCase('S')` print `use_case S;` (invalid).
        # kind= accepts friendly values (usage/definition), the SysML keyword
        # form ("part def"), or the IR kind ("part").  Class-name forms
        # ("PartDefinition") are REJECTED.
        ir = self.ir_kind
        # W2-D: base `Builder` is abstract; reject bare construction.
        if not ir:
            raise TypeError(
                f"{self.__class__.__name__} is abstract; use a generated "
                f"subclass (e.g. Part, Attribute)"
            )
        kw = _IR_KEYWORD[ir]  # strict: a kind the generator forgot -> KeyError
        usage_kw = kw[0]
        def_kw = kw[1] if len(kw) > 1 else None
        # Accept BOTH the IR (underscore) and printable (space) keyword forms
        # for `kind=` (W2-E): 'part'/'use_case' == usage; 'part def'/
        # 'use_case def'/'use case def' == definition.
        _ir_def = f"{ir} def"
        if kind is None or kind == "usage" or kind in (ir, usage_kw):
            self._kind = ir
            self._keyword = usage_kw
        elif kind in ("definition", "def") or kind in (_ir_def, def_kw):
            if def_kw is None:
                raise ValueError(
                    f"{self.__class__.__name__} has no definition form (kind={kind!r})"
                )
            self._kind = _ir_def
            self._keyword = def_kw
            self._is_definition = True  # W2-5: honest introspection + typing guard
        else:
            raise ValueError(
                f"kind={kind!r} not valid for {self.__class__.__name__}; use 'usage'|'definition'"
            )
        # Issue #26: `value=`/`unit=`.  Only Feature-ish kinds carry a value
        # (W2-1) — a free value on Package/Comment/Definition has no IR field
        # and would silently vanish from build().  Refuse rather than emit
        # content that cannot be cast.
        if (value is not None or unit is not None) and not self._can_have_value():
            raise TypeError(
                f"{self.__class__.__name__} (kind {self._kind!r}) cannot carry "
                f"a value/unit — value has no IR field on this kind"
            )
        if value is not None:
            _v, _qspec = self._coerce_value(value)
            if _v is None:
                # value="" or an empty Quantity coerces to no value (W2-1);
                # treat as "no value" so `unit=` still requires a real value,
                # rather than emitting a dangling unit import.
                if unit is not None:
                    raise ValueError(
                        f"value={value!r} is empty; a unit= requires a non-empty value to scale"
                    )
                self._value = None
            else:
                self._value = _v
                # explicit `unit=` must not silently override a Quantity's own
                # unit with no conversion, and must compare against the
                # NORMALIZED bracket, not a raw string (W2-3/W2-4).  Handles
                # both a string and the internal (bracket, bases) pair form so
                # a tuple unit can never silently drop the Quantity's unit
                # (r6 note 1).
                if unit is not None and _qspec is not None:
                    if isinstance(unit, str):
                        try:
                            norm_unit = _normalize_unit_string(unit)
                        except ValueError:
                            norm_unit = unit
                    elif isinstance(unit, tuple) and len(unit) == 2:
                        norm_unit = unit[0]
                    else:
                        norm_unit = None  # non-string/tuple -> _set_unit raises
                    if norm_unit is not None and norm_unit != _qspec[0]:
                        raise ValueError(
                            f"explicit unit={unit!r} conflicts with the "
                            f"Quantity's own unit ({_qspec[0]!r}); pass a "
                            f"converted Quantity or omit unit="
                        )
                self._set_unit(unit if unit is not None else _qspec)
        elif unit is not None:
            # W2-2: a unit with no value is meaningless (no referenced value);
            # reject so we don't emit an import with nothing to apply to.
            raise ValueError(
                f"unit={unit!r} requires a value= (a unit references the value it scales)"
            )
        self._children: list[Builder] = []

    def _can_have_value(self) -> bool:
        """True for kinds with a ``value`` IR field.

        Values are modeled on Feature usages — attribute, part, item,
        reference, and the other usage kinds whose grammar has a ``= value``
        (W2-1).  Package/Comment/Import/Relationship/definition kinds have no
        value IR field, so a ``value=`` there would be silently dropped from
        ``build()`` while showing in ``dump()`` — refuse rather than emit
        content that cannot be cast.
        """
        return self._kind in _VALUE_BEARING_KINDS

    # -- identity -------------------------------------------------------

    def _set_name(self, name, short=False):
        if short:
            self._short_name = name
        else:
            self._name = name
        return self

    def _get_name(self):
        return self._short_name or self._name

    def _set_short_name(self, name):
        self._short_name = name
        return self

    def _set_text(self, text):
        """Set a free-text payload (r2 W2-8; meaningful ONLY for Comment).

        r6 W2-1: text has an IR home (``raw_text``) only for Comment; on any
        other kind there is no IR field that carries it, so setting it would
        silently vanish from ``build()``/``get_definition()`` while showing in
        ``dump()``.  Refuse rather than emit content that cannot be cast.
        """
        if self._kind != "comment":
            raise TypeError(
                f"_set_text is only supported on Comment builders "
                f"(got kind {self._kind!r}; text has no IR field on this kind)"
            )
        self._text = text
        return self

    # -- value (issue #26) ---------------------------------------------

    @staticmethod
    def _coerce_value(value):
        """Normalize a ``value=`` into ``(ir_value_str, unit_spec_or_None)``.

        ``unit_spec`` is ``(bracket_str, [base_name, ...])`` where
        ``bracket_str`` is the normalized ``[ ]`` spelling (``'m/s2'``) and
        the base list drives Option-A imports.  ``None``/``""`` ->
        ``(None, None)``.  A plain ``str``/``int``/``float`` has no unit.  A
        duck-typed astropy Quantity (has ``.value``, ``.unit``, and
        ``.unit.bases`` / ``.unit.powers``) yields its numeric ``.value``
        plus the structured unit.  Anything else raises ``TypeError`` (fail
        fast — must be representable in the IR or it cannot cast).

        The bracket spelling and import bases are BOTH derived from the
        structured ``bases``/``powers`` (not ``to_string()`` string-splitting),
        so composites (``kg m / s2``) never get mangled and the import
        derivation never mis-parses a product.
        """
        if value is None:
            return None, None
        if isinstance(value, str):
            if value == "":
                return None, None
            return value, None
        if isinstance(value, bool):
            # grammar requires lower-case 'true'|'false' (W1-5)
            return "true" if value else "false", None
        if isinstance(value, (int, float)):
            return str(value).removesuffix(".0"), None
        # duck-typed pint Quantity (has ``.magnitude``, ``.units``, and its
        # Unit exposes ``._units`` — a dict of FULL unit name -> exponent).
        # pint folds any scale into the magnitude, so there is no separate
        # ``.scale`` to fail on (unlike astropy).  Map pint's full names to
        # SysML member names + namespaces, then reuse the SAME bracket builder
        # as the string/astropy paths so all three render identically.
        if hasattr(value, "units") and hasattr(value.units, _PINT_UNITS_ATTR):
            pint_dict = getattr(value.units, _PINT_UNITS_ATTR)
            if not isinstance(pint_dict, dict):
                pint_dict = dict(pint_dict)
            bases: list[str] = []
            powers: list[int] = []
            for full_name, exponent in pint_dict.items():
                full_name = str(full_name)
                # fail-loud: an unknown pint unit has no SysML namespace —
                # never emit a silently-wrong model (same rule as astropy)
                if full_name not in _PINT_UNIT_NAMESPACE:
                    raise ValueError(
                        f"pint unit {full_name!r} has no known SysML namespace; "
                        f"decompose to base units (e.g. q.to_base_units()) or "
                        f"pass a named unit the library knows"
                    )
                power = exponent
                if int(power) != power:
                    raise ValueError(
                        f"pint unit power {power!r} on {full_name!r} is not an "
                        f"integer; fractional powers cannot be rendered "
                        f"faithfully in SysML"
                    )
                bases.append(_PINT_UNIT_SYSML_NAME.get(full_name, full_name))
                powers.append(int(power))
            raw = value.magnitude
            if hasattr(raw, "shape") and getattr(raw, "shape", None):
                raise ValueError(
                    f"value= Quantity is non-scalar (shape="
                    f"{raw.shape}); only scalar quantities are supported"
                )
            bracket = _build_unit_bracket(bases, powers)
            if not bases:
                # dimensionless pint Quantity (empty _units) -> no unit
                return str(raw).removesuffix(".0"), None
            return str(raw).removesuffix(".0"), (bracket, bases)
        # duck-typed astropy Quantity
        if (
            hasattr(value, "value")
            and hasattr(value, "unit")
            and hasattr(value.unit, "bases")
            and hasattr(value.unit, "powers")
        ):
            # W2-3: a scaled unit (e.g. u.Unit(100*u.m)) has scale != 1 while
            # decomposing to a single base — folding it would silently change
            # the value, and emitting `[m]` would be 100x wrong.  Fail loud.
            scale = getattr(value.unit, "scale", 1)
            if scale != 1:
                raise ValueError(
                    f"value= Quantity has a multiplicative scaling factor "
                    f"({scale!r}); scaled units cannot be rendered faithfully "
                    f"in SysML — convert to a named unit first"
                )
            bases = [str(b) for b in value.unit.bases]
            raw_powers = list(value.unit.powers)
            # W2-2: non-integer (Fraction/float) powers — int() would silently
            # drop them; fail loud instead
            for bp in raw_powers:
                if int(bp) != bp:
                    raise ValueError(
                        f"unit power {bp!r} is not an integer; fractional "
                        f"powers cannot be rendered faithfully in SysML"
                    )
            powers = [int(p) for p in raw_powers]
            raw = value.value
            if hasattr(raw, "shape") and getattr(raw, "shape", None):
                # a non-scalar Quantity (array) can't render as a single valued
                # literal in the IR — fail loud instead of emitting `= [1. 2.]`
                raise ValueError(
                    f"value= Quantity is non-scalar (shape="
                    f"{raw.shape}); only scalar quantities are supported"
                )
            # W2-1: a dimensionless Quantity (empty bases) carries no unit at
            # all — emit the bare value, no bracket, no import
            bracket = _build_unit_bracket(bases, powers)
            if not bases:
                return str(raw).removesuffix(".0"), None
            return str(raw).removesuffix(".0"), (bracket, bases)
        raise TypeError(
            f"value= must be str/int/float or an astropy Quantity, got {type(value).__name__}"
        )

    # -- unit handling -------------------------------------------------

    def _set_unit(self, unit_string: str | None) -> None:
        """Validate + normalize a raw ``unit=`` string into
        ``(bracket_str, [base, ...])`` and store it (fail-loud, W2-2/W1-3).

        A raw string form (``'m/s2'``) is parsed into bracket + bases by
        splitting on ``/``/``*`` and stripping powers; a structured spec
        (from a Quantity) is taken as-is.  Storing the normalized form ONCE
        means ``_to_ir``, ``_render_sysml`` and ``Node.dump`` all agree.
        """
        if unit_string is None:
            self._unit = None
            self._unit_bases = None
            return
        if not isinstance(unit_string, str):
            if isinstance(unit_string, tuple) and len(unit_string) == 2:
                bracket, bases = unit_string
            else:
                # e.g. an astropy Unit like u.m (not a Quantity) — it has no
                # string base to parse.  Fail loud with a clear message (r4).
                raise TypeError(
                    f"unit= must be a string like 'm'/'kg'/'m/s**2', a "
                    f"(bracket, bases) pair, or come from a value= Quantity; "
                    f"got {type(unit_string).__name__}. Pass a string unit, "
                    f"or wrap it in a Quantity (e.g. value=1*u.m)."
                )
        else:
            bases = _split_unit_bases(unit_string)
            # normalize to the SysML bracket (whitespace + exponent operator
            # + quoting), which also validates a parseable base exists; this is
            # idempotent on the builder's own emitted spelling (r4 W1-1)
            bracket = _normalize_unit_string(unit_string)
        # a unit with no parseable base is meaningless (W2-1): an empty string
        # or a bare magnitude like '123' yields no import and a bogus `[ ]`
        # bracket — fail loud rather than emit a dangling unit
        if not bases:
            raise ValueError(
                f"unit={unit_string!r} has no parseable unit base; expected "
                f"something like 'm', 'kg', 'm/s**2' (got no unit name)"
            )
        if not bracket:
            raise ValueError(
                f"unit={unit_string!r} normalizes to an empty unit; expected e.g. 'm/s2'"
            )
        # fail-loud: every base must be mappable before we store it
        for base in bases:
            self._unit_to_namespace(base)
        self._unit = bracket
        self._unit_bases = bases

    @staticmethod
    def _unit_to_namespace(unit_name: str) -> str:
        """Map an astropy base-unit name to its SysML namespace (issue #26,
        Option A, fail-loud).  Raise ValueError for unmapped units so a
        value= quantity can never generate a silently-wrong model.  (ValueError
        — not NotImplementedError — to preserve the parser-lossless
        zero-NotImplemented acceptance invariant, issue #9: unsupported
        *parser* constructs are preserved, never raised.)"""
        ns = _UNIT_NAMESPACE.get(unit_name)
        if ns is None:
            raise ValueError(
                f"unit {unit_name!r} is not in the built-in unit map "
                f"(issue #26); add it to _UNIT_NAMESPACE or use a plain "
                f"string value with no unit"
            )
        return ns

    def _unit_imports(self) -> list[tuple[str, str]]:
        """The ``(namespace, sysml-name)`` imports this node requires (Option A).
        Derived from the stored structured unit bases — never string-split at
        render time.  Names go through the SysML map + quoting so `in` -> `'in'`
        and `gallon` -> `gal` are consistent with the bracket (W2-4/5)."""
        bases = getattr(self, "_unit_bases", None)
        if not bases:
            return []
        imports: list[tuple[str, str]] = []
        for base in bases:
            ns, sysml_name = _unit_import_spec(base)
            if (ns, sysml_name) not in imports:
                imports.append((ns, sysml_name))
        return imports

    def _collect_unit_imports(self) -> list[tuple[str, str]]:
        """Collect the union of unit imports this subtree references, walking
        descendants (issue #26, Option A).

        Returns ``(namespace, unit)`` pairs in deterministic order.  The
        walk is deterministic (not necessarily source-document order — N-3).
        A user-authored ``Import`` child whose name already matches an
        auto-derived unit (e.g. ``public import SI::kg;``) is NOT re-emitted:
        the name ``<ns>::<unit>`` is compared against every existing Import
        child's name so we never double-import (W2-2).
        """
        seen: list[tuple[str, str]] = []
        existing = self._existing_import_names()
        stack = [self]
        while stack:
            node = stack.pop()
            for imp in node._unit_imports():
                # skip if an existing Import member already declares it
                fq = f"{imp[0]}::{imp[1]}"
                if fq in existing:
                    continue
                if imp not in seen:
                    seen.append(imp)
            stack.extend(c for c in node._children if c is not None)
        return seen

    def _existing_import_names(self) -> set[str]:
        """Names of `import` members already present in this subtree (W2-2).

        When a user authors their own ``ImportBuilder("SI::kg")`` child, the
        auto-importer must not also emit ``public import SI::kg;``."""
        names: set[str] = set()
        stack = [self]
        while stack:
            node = stack.pop()
            if getattr(node, "_kind", "") == "import":
                name = node._name or ""
                if "::" in name:
                    ns, unit = name.split("::", 1)
                    # normalize the unit segment to the SysML spelling +
                    # quoting so a user-authored `USCustomaryUnits::in` dedups
                    # against the auto `USCustomaryUnits::'in'` (r4).
                    name = f"{ns}::{_quote_unit_name(_unit_sysml_name(unit))}"
                names.add(name)
            stack.extend(c for c in node._children if c is not None)
        return names

    def _root_with_imports(self):
        """The root builder with any auto-imports prepended as real members.

        Called by ``dump()``/``build()``/``build_node()`` on the OUTERMOST
        builder so the imports are structural and consistent across every
        emit path.  Returns a shallow copy — the original ``_children`` is not
        mutated, so a nested/member ``_render_sysml`` call never re-adds them.

        Imports are only materialized when the root actually renders a
        ``{...}`` member body (i.e. it has real children).  A bare, childless
        root — e.g. a lone ``Attribute(value=...)`` — has no body to host an
        import and emits ``attribute t = 2.5[s];`` with no import (matching
        the corpus: imports live at the owning container).
        """
        real_kids = [c for c in self._children if c is not None]
        if not real_kids:
            return self  # no member body to host imports
        imps = self._collect_unit_imports()
        if not imps:
            return self
        import copy

        clone = copy.copy(self)
        # prepend imports so they open the body (corpus: `public import` first)
        imports = []
        for ns, unit in imps:
            imp = ImportBuilder(f"{ns}::{unit}")
            # KERML-74: ImportBuilder already defaults visibility to public
            # (via __init__), so `_set_visibility("public")` is idempotent —
            # do NOT also set _modifiers["public"], or emission renders
            # `public public import` (r#23 caught the duplicate).
            imp._set_visibility("public")
            imports.append(imp)
        clone._children = imports + clone._children
        return clone

    # -- modifiers ------------------------------------------------------

    def _set_direction(self, value=None):
        """Set the ``in out inout`` modifier(s)."""

        # enum: validate against the allowed tokens, key by slot NAME
        # (emission emits the bare value, W1-3 / r3 W2-12).
        if value not in ("in", "out", "inout"):
            raise ValueError("direction must be one of in, out, inout, got " + repr(value))
        self._modifiers["direction"] = value

        return self

    def _set_isAbstract(self, value=None):
        """Set the ``abstract`` modifier(s)."""

        # W2-11: clear mutually-exclusive modifiers so e.g. abstract+variation
        # can never both render.

        self._modifiers.pop("variation", None)

        self._modifiers["abstract"] = True if value is None else value

        return self

    def _set_isVariation(self, value=None):
        """Set the ``variation`` modifier(s)."""

        # W2-11: clear mutually-exclusive modifiers so e.g. abstract+variation
        # can never both render.

        self._modifiers.pop("abstract", None)

        self._modifiers["variation"] = True if value is None else value

        return self

    def _set_isReadOnly(self, value=None):
        """Set the ``readonly`` modifier(s)."""

        # W2-11: clear mutually-exclusive modifiers so e.g. abstract+variation
        # can never both render.

        self._modifiers["readonly"] = True if value is None else value

        return self

    def _set_isDerived(self, value=None):
        """Set the ``derived`` modifier(s)."""

        # W2-11: clear mutually-exclusive modifiers so e.g. abstract+variation
        # can never both render.

        self._modifiers["derived"] = True if value is None else value

        return self

    def _set_isEnd(self, value=None):
        """Set the ``end`` modifier(s)."""

        # W2-11: clear mutually-exclusive modifiers so e.g. abstract+variation
        # can never both render.

        self._modifiers["end"] = True if value is None else value

        return self

    def _set_isReference(self, value=None):
        """Set the ``ref`` modifier(s)."""

        # W2-11: clear mutually-exclusive modifiers so e.g. abstract+variation
        # can never both render.

        self._modifiers["ref"] = True if value is None else value

        return self

    # -- typing ---------------------------------------------------------

    def _set_typed_by(self, typed):
        if not isinstance(typed, Builder):
            raise TypeError("_set_typed_by expects a Builder")
        if self._is_definition:
            raise ValueError("A definition element cannot be typed.")
        self._typed_by = typed
        return self

    def _set_multiplicity(self, mult):
        """Set the multiplicity (r3 W2-14); e.g. ``_set_multiplicity("1..*")``.
        Accepted as ``[1..*]`` or bare ``1..*``; emitted in brackets."""
        m = mult if isinstance(mult, str) else str(mult)
        self._multiplicity = m.strip("[]")
        return self

    # -- children -------------------------------------------------------

    def _set_child(self, child):
        if not isinstance(child, Builder):
            raise TypeError("_set_child expects a Builder")
        self._children.append(child)
        return self

    def add(self, child):
        """Ergonomic alias for ``_set_child`` (issue #27) — append a child so
        nested composition dumps a full package: ``pkg.add(part)``."""
        return self._set_child(child)

    def is_legal_child(self, child):
        """Advisory child-kind legality (W1-5/r3 W1-4/r4 #1/r5 W1-1).

        ``child.kind`` must appear among this builder's owned-body's legal
        child kinds (children.json) when that body is a known key; otherwise
        conservatively True (r5 W1-1).  Usage builders own ``DefinitionBody``
        whose slot kinds are exactly the builder vocabulary.  Package bodies
        additionally accept ALL usage kinds (children.json ``PackageBody``
        only lists definitions, but a package legitimately contains
        `part`/`attribute`/etc. members — r4 #1), so the usage kinds from
        ``DefinitionBody`` are unioned in.  Bodies not present in
        children.json (e.g. ``RelationshipBody`` for Import) have no
        membership data → never reject.
        """
        body = self.owned_body
        if body is None:
            # owns no body at all (e.g. _DefaultReferenceBuilder) — reject all
            return False
        if body not in LEGAL_CHILDREN:
            return True  # no membership data for this body — never reject
        allowed = LEGAL_CHILDREN[body]
        if body == "PackageBody":
            allowed = set(allowed) | set(LEGAL_CHILDREN.get("DefinitionBody", ()))
        return child.kind in allowed

    def _get_child(self, featurechain):
        return _walk_chain(self, featurechain)

    # -- directed features ----------------------------------------------

    def add_directed_feature(self, direction, name=None, *, kind_name="DefaultReferenceUsage"):
        if direction not in ("in", "out", "inout"):
            raise ValueError(f"direction must be in/out/inout, got {direction!r}")
        cls = _BUILDER_BY_NAME.get(kind_name, _DefaultReferenceBuilder)
        feat = cls(name)
        feat._set_direction(direction)
        self._set_child(feat)
        return self

    def _get_grammar(self):
        return self.build_node()

    def build(self, dict_=True):
        d = self._root_with_imports()._to_ir()
        return d if dict_ else Node.from_ir(d)

    def build_node(self):
        return Node.from_ir(self._root_with_imports()._to_ir())

    def dump(self):
        from .ast_classes import beautify

        text = self._root_with_imports()._render_sysml()
        if text.strip():
            return beautify(text)
        return text

    def _render_sysml(self) -> str:
        """Render this builder subtree as textual SysML.

        Emits a ``KIND name`` header (modifiers upstream, short name as
        ``<s>``) and ``{ child ... }`` body braces.  Uses the coarse canonical
        IR kind + grammar modifier tokens (W1-3) so the header vocabulary
        matches ``parse_ir``.  ``;`` terminates childless statements (r3
        W1-8) so multi-member brace blocks recover as separate IR statements;
        ``/* */`` free text for Comment (r3 W1-7).
        """
        # r6: _set_text is Comment-only (raises otherwise, W2-1), so no
        # non-comment carry of _text through _render_sysml is needed.
        if self._text is not None and self._kind == "comment":
            # Comment payload is free text (r3 W1-7): self-terminating so
            # parse_ir yields a comment node rather than an unknown.
            return f"/* {self._text} */"

        # W2-10: emit modifiers in canonical slot order, not insertion order,
        # so e.g. `abstract` before ``out`` (valid RefPrefix) survives.
        mods: list[str] = []
        for _name, _tokens, _kind in _MODIFIER_SLOTS:
            # flags are stored by TOKEN ('abstract'), enums by NAME ('direction') —
            # r4 #2: look up by the correct key or slot-order emission never fires.
            key = _tokens[0] if _kind == "flag" else _name
            v = self._modifiers.get(key)
            if v is None or v is False:
                continue
            if v is True:
                mods.append(_tokens[0])
            elif isinstance(v, str):
                mods.append(v)  # enum — bare value (W1-3)
            else:
                mods.append(f"{_name}={v}")
        for k, v in self._modifiers.items():
            if any(
                (s[2] == "flag" and k in s[1]) or (s[2] != "flag" and s[0] == k)
                for s in _MODIFIER_SLOTS
            ):
                continue
            if v is True:
                mods.append(k)
            elif isinstance(v, str):
                mods.append(v)
            elif v is not None and v is not False:
                mods.append(f"{k}={v}")
        # KERML-74: textual import declarations REQUIRE an explicit visibility
        # indicator (`public import`, `private import`, `protected import`) —
        # bare `import X::*;` is spec-invalid (windtrader-java #10 triage).
        # The corpus correction (PR #22) and the pre-KERML-74 default were
        # `public`.  `ImportBuilder.__init__` is the SINGLE source of truth for
        # the default (it sets `_modifiers["visibility"] = "public"`), so by
        # the time we render, `visibility` is always present and this catch-all
        # loop alone carries it — there is deliberately NO render-side fallback
        # here: a fallback with no `_to_ir()` counterpart would break the cast
        # (emission saying `public` while the model carries no modifier).
        mod_txt = (" ".join(mods) + " ") if mods else ""
        # Issue #27: `self._kind` is the coarse canonical-IR kind (part /
        # attribute / ...) OR the definition-variant keyword ("part def").
        # NEVER fall back to the class name (old `__class__.__name__
        # .replace("Builder","")` emitted `PartDefinition S;` for
        # kind='PartDefinition' — invalid SysML v2).  W1-3: print the
        # printable SysML keyword (`use case`, not the IR alias key
        # `use_case`).  Fall back to `self._kind` only so the base/default
        # path (which may not have set `_keyword` via __init__) still prints.
        keyword = getattr(self, "_keyword", None) or self._kind or self.ir_kind
        head = f"{mod_txt}{keyword}"
        if self._short_name is not None:
            head += f" <{self._short_name}>"  # r3 W1-5: angle (parse_ir vocab)
        if self._name is not None:
            head += f" {self._name}"
        if self._multiplicity is not None:
            head += f" [{self._multiplicity}]"
        if self._typed_by is not None:
            head += f" : {self._typed_by._name}"
        # Issue #26: value (and optional unit) — `attribute mass = 1000[kg];`
        # value+unit with NO space between them (corpus).  Plain string value
        # (no unit) renders `attribute mass = 1000;`.
        if self._value is not None:
            if self._unit:
                head += f" = {self._value}[{self._unit}]"
            else:
                head += f" = {self._value}"
        lines = [head]
        kids = [c for c in self._children if c is not None]
        # (rest unchanged) — indentation/termination follows
        if kids:
            lines.append("{")
            for c in kids:
                lines.append(c._render_sysml())
            lines.append("}")
        else:
            lines[0] = head + ";"  # r3 W1-8: terminate childless statements
        return "\n".join(lines)

    def _to_ir(self):
        d: dict[str, object] = {"kind": self._kind}
        if self._name is not None:
            d["name"] = self._name
        if self._short_name is not None:
            d["short_name"] = self._short_name
        if self._text is not None and self._kind == "comment":
            # r5 W2-3: text is only persisted to raw_text for Comment.  For
            # other kinds the text is rendered by _render_sysml (appended after
            # the header) but must NOT go into raw_text, or Node.dump() would
            # prefer raw_text and drop the header + glue the subtree.
            d["raw_text"] = self._text
        if self._multiplicity is not None:
            d["multiplicity"] = self._multiplicity
        if self._value is not None:
            d["value"] = self._value
            if self._unit:
                d["unit"] = self._unit
        mods: list[str] = []
        for _nm, _tk, _kd in _MODIFIER_SLOTS:
            key = _tk[0] if _kd == "flag" else _nm
            v = self._modifiers.get(key)
            if v is None or v is False:
                continue
            if v is True:
                mods.append(_tk[0])
            elif isinstance(v, str):
                mods.append(v)
            else:
                mods.append(f"{_nm}={v}")
        for k, v in self._modifiers.items():
            if any(
                (s[2] == "flag" and k in s[1]) or (s[2] != "flag" and s[0] == k)
                for s in _MODIFIER_SLOTS
            ):
                continue
            if v is True:
                mods.append(k)
            elif isinstance(v, str):
                mods.append(v)
            elif v is not None and v is not False:
                mods.append(f"{k}={v}")
        if mods:
            d["modifiers"] = mods
        if self._typed_by is not None:
            # B1/W2-5: type_refs is the _NODE_IR_FIELDS key that carries the
            # typed reference (typed_by was never in the AST IR and would
            # throw).  Use the referent's _name to match the name IR field.
            d["type_refs"] = [self._typed_by._name]
        kids = [c for c in self._children if c is not None]
        if kids:
            d["children"] = [c._to_ir() for c in kids]
        return d


class _DefaultReferenceBuilder(Builder):
    kind = "DefaultReferenceUsage"
    ir_kind = "reference"
    owned_body = None


def _walk_chain(root, featurechain):
    """Resolve a dotted feature chain ('x.y.z') under ``root``.

    A leading self-name segment (matched against the root's effective name)
    is tolerated (0.5.3 _get_child behaviour) and skipped.
    """
    if not isinstance(featurechain, str):
        raise TypeError("featurechain must be a str")
    fc = featurechain.split(".")
    # r4 #7: match the root self-name against LONG or SHORT name (was
    # _get_name() which preferred short name, breaking long chains).
    if fc and fc[0] in (root._name, root._short_name):
        fc = fc[1:]
        if not fc:
            return root
    cur = root
    for seg in fc:
        found = None
        for child in cur._children:
            # W2-15 (r3): match the LONG name first, then the short name, so a
            # dotted chain keeps resolving even when a member has a short name.
            if child._name == seg or child._short_name == seg:
                found = child
                break
        if found is None:
            return None
        cur = found
    return cur


