class ImportBuilder(Builder):
    """Builder for a Import (IR kind: import)."""

    kind = "Import"
    ir_kind = "import"
    owned_body = "RelationshipBody"

    # KERML-74: textual imports REQUIRE an explicit visibility indicator
    # (`public|private|protected import …;`); bare `import …;` is
    # spec-invalid (windtrader-java #10 triage).  The builder defaults an
    # import to `public` so `_to_ir()` carries the modifier AND emission
    # renders it — model and text agree, so the cast holds
    # element-for-element (re-parsing `public import` yields
    # modifiers=['public']).  Users can switch via `_set_visibility`.
    def __init__(self, name=None, *, kind=None, value=None, unit=None):
        super().__init__(name, kind=kind, value=value, unit=unit)
        if self._modifiers.get("visibility") is None:
            self._modifiers["visibility"] = "public"

    def _set_visibility(self, value=None):
        """Set the import's visibility indicator (KERML-74).

        Accepts ``public`` / ``private`` / ``protected`` (or no value, which
        defaults to ``public``).  Mutually exclusive: setting one clears the
        others so e.g. ``public+private`` can never render.
        """
        if value is None:
            value = "public"
        if value not in ("public", "private", "protected"):
            raise ValueError(
                f"invalid visibility {value!r}; expected 'public', 'private' or 'protected'"
            )
        for tok in ("public", "private", "protected"):
            self._modifiers.pop(tok, None)
        self._modifiers["visibility"] = value
        return self


